// Extraer datos del mensaje
const payload = $json;
const mensajes = payload?.messages || [payload];
const msg = mensajes[0] || payload;

const phone = msg?.from || 'unknown';
const texto = (msg?.body || msg?.text || '').toLowerCase().trim();
const nombre = msg?.pushName || 'Cliente';

return [{json: {
  phone: phone,
  nombre: nombre,
  texto: texto,
  es_nuevo: texto === 'hola' || texto === 'buenas' || texto === ' inicio'
